INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"status": "draft", "name": "朱元璋", "aliases": [], "era": "元末明初", "birth_year": null, "death_year": null, "description": "钟离人，少因饥疫丧家出家皇觉寺，1352年投郭子兴于濠州，后娶其养女。", "biography": null, "id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e"}, {"name": "常遇春", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "怀远人，1355年投朱元璋、采石先登。", "biography": null, "status": "draft", "id": "51d50a75-07e1-574f-b22d-1fded66288ff"}, {"name": "徐达", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "濠州人，1353年随朱元璋南略。", "biography": null, "status": "draft", "id": "0f28446e-78b0-5db1-9677-98777005803e"}, {"name": "李思齐（元汝宁知府）", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "信阳罗山人，与察罕特穆尔起兵攻罗山，获授汝宁知府；与1177年宋金州副都统制李思齐分开。", "biography": null, "status": "draft", "id": "7fe5f4f8-f174-51cd-aafc-db1d10c279c1"}, {"name": "冯国胜", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "吴将，参与伏击陈友谅及追击战。", "biography": null, "status": "draft", "id": "11681f87-f6f7-58db-93b2-dad66d159d27"}, {"name": "李文忠", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "朱元璋姊子，1354年归舅获赐朱姓。", "biography": null, "status": "draft", "id": "937816d2-8a96-5b84-9cae-f26cdcacfa7b"}, {"name": "库库特穆尔（察罕特穆尔养子）", "aliases": [], "era": "元末", "birth_year": null, "death_year": null, "description": "本姓王名保保，察罕外甥，养为子；继掌其军。", "biography": null, "status": "draft", "id": "c00ceaa1-c47d-5d7f-bbe7-4c2ba9cfe8df"}, {"name": "汤和", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "1355年夺桥取和阳，后从朱渡江。", "biography": null, "status": "draft", "id": "76a3c1b3-e175-593d-99d7-63da30cef072"}, {"name": "杨璟", "aliases": [], "era": "元", "birth_year": null, "death_year": null, "description": "吴亲军副都指挥，1358年随朱攻婺。", "biography": null, "status": "draft", "id": "de35b4c9-584c-5f2a-b297-a979743d7555"}]'::jsonb)
