INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "明廷在鸡笼山建立功臣庙", "description": "洪武二年正月乙巳，明廷在鸡笼山建立功臣庙。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "adbafc0a-b8e9-5e2c-9dae-c023bb7682a6"}, {"title": "明廷祭祀太庙", "description": "正月丁未，明廷在太庙举行祭祀。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a5aaa0b9-f80e-5f85-a354-f13aadd2fab2"}, {"title": "朱元璋减免北方多地田租", "description": "正月庚戌，朱元璋说北方百姓久受战乱和征收之苦，下令免除北平、燕南、河东、山西等地当年田租，并减免山东、河南等地税粮。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4a48b6ce-d2df-5e12-a10e-59d19ab1a5e6"}, {"title": "朱元璋减免应天等地租税", "description": "朱元璋另下诏说，应天、太平等地供应军需负担很重，去年虽减税，又遇旱灾，百姓所得有限。他下令免除这些地方及无为州当年的租税。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6e5672ea-41cc-5c71-ac14-354e936b06c7"}, {"title": "常遇春攻取大同", "description": "正月庚申，常遇春攻取大同。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "24597379-c19e-5f4b-a315-8623469e3722"}, {"title": "山东沿海州县遭到侵扰", "description": "正月，山东沿海州县遭到史书所称的倭寇侵扰。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ca0c3c7d-50d1-5e32-87ec-3c2a9f83dc00"}, {"title": "朱元璋下诏编修《元史》", "description": "二月初一，朱元璋下诏编修《元史》。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "936f68d0-b9dc-5dbf-ac8b-b46ecc9edb4f"}, {"title": "朱元璋举行耕耤礼", "description": "二月壬午，朱元璋举行耕耤礼，亲自耕作朝廷的礼田。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "bf765318-6948-5eb5-8112-bbf3b792606a"}, {"title": "徐达进至奉元", "description": "三月庚子，徐达率军到奉元，张思道逃走。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4202848b-a8aa-531d-aafc-e5ccc97ce815"}, {"title": "明廷发粮赈济陕西饥民", "description": "三月，明廷向陕西饥民发放赈粮，本纪记每户发米三石。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c5f502cf-ed8d-5bdf-b7c5-1ed6c485a06c"}, {"title": "常遇春进至凤翔", "description": "三月丙午，常遇春率军到凤翔，李思齐逃往临洮。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年三月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8c11e1c6-eb37-5403-af5e-e8e7d96e1116"}, {"title": "常遇春率军返回北平", "description": "四月丙寅，常遇春率军返回北平。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "039d0664-8840-51eb-abe7-8fc9fb272bbe"}, {"title": "皇子从孔克仁学习经书", "description": "四月己巳，皇子们跟随博士孔克仁学习经书。明廷还令功臣的子弟入学。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7ef5c3d3-a035-5815-91b5-431247a6e1b9"}, {"title": "明廷编纂《祖训录》并制定诸王分封制度", "description": "四月乙亥，明廷编纂《祖训录》，制定分封诸王的制度。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ff1490b6-2a5f-510f-a8fe-96a7de1e08e6"}, {"title": "徐达攻下巩昌", "description": "四月，徐达攻下巩昌。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "fe7b5531-0640-5de3-8c86-31ebe21f58b6"}, {"title": "冯胜进至临洮，李思齐归降", "description": "四月丁丑，冯胜率军到达临洮，李思齐归降。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年四月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknow