": 1369, "end_year": 1369, "time_original": "洪武二年六月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "87119f7d-5b08-5cba-8ab3-4a0dd6d635e8"}, {"title": "常遇春在军中去世，李文忠接掌其部", "description": "七月己亥，鄂国公常遇春在军中去世。朱元璋下诏由李文忠统领他的部队。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "dfd5cdb9-0db9-5eb3-901a-7d5fd4f83094"}, {"title": "扩廓帖木儿遣将攻原州、泾州", "description": "七月辛亥，扩廓帖木儿派将领攻破原州和泾州。辛酉，冯胜击退这支部队。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年七月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "03a7b9ca-d82e-56b1-b0fd-706f75b07035"}, {"title": "李文忠击退进攻大同的元军", "description": "八月丙寅，元军攻打大同，李文忠将其击败。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "28af9e31-6991-52f0-b8f9-37c10730f941"}, {"title": "明廷制定内侍官制", "description": "八月己巳，明廷制定内侍官制。朱元璋要求内侍人数从简，用法律约束内侍。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "601cae6f-eab3-535a-8f09-a6fcb5e48bb7"}, {"title": "《元史》编成", "description": "八月癸酉，本纪记《元史》编成。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "43f01108-f079-5a6a-acf5-a8df8b1586a2"}, {"title": "明廷封王颛为高丽国王", "description": "八月丙子，明廷封王颛为高丽国王。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "54c1acf5-5a7b-515a-9b7b-36ca5d3426ce"}, {"title": "徐达攻克庆阳", "description": "八月癸未，徐达攻克庆阳，处死张良臣。史书记陕西平定。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年八月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "8fa4fe49-4aed-5a45-bbee-28fc766e31fa"}, {"title": "明廷召回徐达、汤和，留冯胜领军", "description": "九月辛丑，朱元璋召徐达、汤和回朝，留下冯胜总领当地军务。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cc599941-ef8c-5d0a-beba-48fce44cb343"}, {"title": "明廷定临濠为中都", "description": "九月癸卯，明廷定临濠为中都。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年九月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "09ba1f62-91e4-5871-9e40-1bf0df263910"}, {"title": "杨璟奉命告谕明升", "description": "十月壬戌，朱元璋派杨璟前去告谕明升。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4021efdf-36ba-56e0-a07d-b9d2f716b3ad"}, {"title": "明廷下诏各州县设学", "description": "十月辛卯，明廷下诏，命各地府州县设立学校。", "start_year": 1369, "end_year": 1369, "time_original": "洪武二年十月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a2239691-8176-522b-bb40-2268c652de24"}, {"title": "明廷在圜丘祭祀上帝", "description": "十一月乙巳，明廷在圜丘祭祀上帝，让仁祖配享。 按原历纪年，事情发生在公元1369至1370年之间。", "start_year": null, "end_year": null, "time_original": "洪武二年十一月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f04ecb30-7bc1-5451-b911-994e36815d14"}, {"title": "明廷封阿答阿者为占城国王", "description": "十二月甲戌，明廷封阿答阿者为占城国王。", "start_year": 1370, "end_year": 1370, "time_original": "洪武二年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "749570ce-9f9a-5188-8227-03ea821b616c"}, {"title": "明廷发粮赈济西安等地饥民", "description": "十二月甲申，明廷向西安等地遭饥荒的百姓发放粮食，本纪记每户给米二石。", "start_year": 1370, "end_year": 1370, "time_original": "洪武二年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cc9ed658-bb14-5ecb-8581-508cadde48ac"}, {"title": "明廷赏赐平定中原和征南的将士", "description": "十二月己丑，明廷对参加平定中原及征南的将士发给赏赐。", "start_year": 1370, "end_year": 1370, "time_original": "洪武二年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5b348b68-4ba2-543e-8502-22e9bcf796c6"}, {"title": "扩廓帖木儿进攻兰州", "description": "十二月庚寅，扩廓帖木儿率部进攻兰州，明军指挥于光在这次战事中身亡。", "start_year": 1370, "end_year": 1370, "time_original": "洪武二年十二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "29e5319d-1190-58e5-81fd-1aa3cfe65ec7"}, {"title": "本纪记占城、安南和高丽进贡", "description": "洪武二年，史书记占城、安南和高丽向明廷进贡。 按原历纪年，事情发生在公元1369至1370年之间。", "start_year": null, "end_year": null, "time_original": "洪武二年本年所叙，月份承前或未单标", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6ae2f9f9-ba3f-56ef-b4f3-34cb6430231f"}]'::jsonb)
