INSERT INTO public.fact_claim (id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status)
SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "洪武二年正月乙巳，明廷在鸡笼山建立功臣庙。", "citation": "《明史》卷2·本纪第二·太祖二·mingshi-2f603db3d81e-p000496；洪武二年正月", "note": "原文：二年春正月乙巳，立功臣廟於雞籠山。；核对说明：该摘录逐字支持所列行动及其阶段；时间取本段及相邻年条。", "status": "draft", "id": "9dd9e501-c0f3-5af7-8cf4-aa768de1ce66", "subject_id": "adbafc0a-b8e9-5e2c-9dae-c023bb7682a6", "source_id": "b5972b42-8e24-5a68-977e-16061d0248d8"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历洪武二年正月。DDBC历表所涉区间为1369-02-15至1369-03-16，据此核对公元发生年份。", "citation": "《明史》卷2·本纪第二·太祖二·mingshi-2f603db3d81e-p000496；洪武二年正月", "note": "原文：二年春正月乙巳，立功臣廟於雞籠山。；核对说明：原历纪年按本段及相邻年条核对，史料未载的具体日保留为空。", "status": "draft", "id": "960d83bf-766e-5513-8f1d-fe1a23a11111", "subject_id": "adbafc0a-b8e9-5e2c-9dae-c023bb7682a6", "source_id": "b5972b42-8e24-5a68-977e-16061d0248d8"}, {"subject_table": "event", "field_path": "description", "claim_text": "正月丁未，明廷在太庙举行祭祀。", "citation": "《明史》卷2·本纪第二·太祖二·mingshi-2f603db3d81e-p000496；洪武二年正月", "note": "原文：丁未，享太廟。；核对说明：该摘录逐字支持所列行动及其阶段；时间取本段及相邻年条。", "status": "draft", "id": "297bc75e-3450-533b-8795-28b17bc16a8e", "subject_id": "a5aaa0b9-f80e-5f85-a354-f13aadd2fab2", "source_id": "b5972b42-8e24-5a68-977e-16061d0248d8"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历洪武二年正月。DDBC历表所涉区间为1369-02-15至1369-03-16，据此核对公元发生年份。", "citation": "《明史》卷2·本纪第二·太祖二·mingshi-2f603db3d81e-p000496；洪武二年正月", "note": "原文：丁未，享太廟。；核对说明：原历纪年按本段及相邻年条核对，史料未载的具体日保留为空。", "status": "draft", "id": "eaa2cebe-bb58-5b05-a7e5-2119eaab88bf", "subject_id": "a5aaa0b9-f80e-5f85-a354-f13aadd2fab2", "source_id": "b5972b42-8e24-5a68-977e-16061d0248d8"}, {"subject_table": "person", "field_path": "description", "claim_text": "本纪记朱元璋，在此事中下令减免北方田租和税粮。", "citation": "《明史》卷2·本纪第二·太祖二·mingshi-2f603db3d81e-p000496；元末，原文未载这项身份的具体年月", "note": "原文：二年春正月乙巳，立功臣廟於雞籠山。丁未，享太廟。庚戌，詔曰：「朕淮右布衣，因天下亂，率眾渡江，保民圖治，今十有五年。荷天眷祐，悉皆戡定。用是命將北征，齊、魯之民饋糧給軍，不憚千里。朕軫厥勞，已免元年田租。遭旱民未蘇，其更賜一年。頃者，大軍平燕都，下晉、冀，民被兵燹，困征斂，北平、燕南、河東、山西今年田租亦與蠲免。河南諸郡歸附，久欲惠之，西北未平，師過其地，是以未遑。今晉、冀平矣，西抵潼關，北界大河，南至唐、鄧、光、息，今年稅糧悉除之。」又詔曰：「應天、太平、鎮江、宣城、廣德供億浩穰。去歲蠲租，遇旱惠不及下。其再免諸郡及無為州今年租稅。」庚申，常遇春取大同。是月，倭寇山東濱海郡縣。；核对说明：按该段身份、官职、人物关系和相邻记载对照规范人物。原字保存在引文中。", "status": "draft", "id": "b64c2145-0e2d-523f-a740-34f33897abf8", "subject_id": "3d83c7c6-23fc-5e89-9e9b-b70713a0a63e", "source_id": "b5972b42-8e24-5a68-977e-16061d0248d8"}, {"subject_table": "event", "field_path": "description", "claim_text": "正月庚戌，朱元璋说北方百姓久受战乱和征收之苦，下令免除北平、燕南、河东、山西等地当年田租，并减免山东、河南等地税粮。", "citation": "《明史》卷2·本纪第二·太祖二·mingshi-2f603db3d81e-p000496；洪武二年正月", "note": "原文：二年春正月乙巳，立功臣廟於雞籠山。丁未，享太廟。庚戌，詔曰：「朕淮右布衣，因天下亂，率眾渡江，保民圖治，今十有五年。荷天眷祐，悉皆戡定。用是命將北征，齊、魯之民饋糧給軍，不憚千里。朕軫厥勞，已免元年田租。遭旱民未蘇，其更賜一年。頃者，大軍平燕都，下晉、冀，民被兵燹，困征斂，北平、燕南、河東、山西今年田租亦與蠲免。河南諸郡歸附，久欲惠之，西北未平，師過其地，是以未遑。今晉、冀平矣，西抵潼關，北界大河，南至唐、鄧、光、息，今年稅糧悉除之。」又詔曰：「應天、太平、鎮江、宣城、廣德供億浩穰。去歲蠲租，遇旱惠不及下。其再免諸郡及無為州今年租稅。」庚申，常遇春取大同。是月，倭寇山東濱海郡縣。；核对说明：该摘录逐字支持所列行动及其阶段；时间取本段及相邻年条。", "status": "draft", "id": "e4f498ee-9dca-572b-bd1d-eb8cac603ba0", "subject_id": "4a48b6ce-d2df-5e12-a10e-59d19ab1a5e6", "source_id": "b5972b42-8e24-5a68-977e-16061d0248d8"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "原历洪武二年正月。DDBC历表所涉区间为1369-02-15至1369-03-16，据此核对公元发生年份。", "citation": "《明史》卷2·本纪第二·太祖二·mingshi-2f603db3d81e-p000496；洪武二年正月", "note": "原文：二年春正月乙巳，立功臣廟於雞籠山。丁未，享太廟。庚戌，詔曰：「朕淮右布衣，因天下亂，率眾渡江，保民圖治，今十有五年。荷天眷祐，悉皆戡定。用是命將北征，齊、魯之民饋糧給軍，不憚千里。朕軫厥勞，已免元年田租。遭旱民未蘇，其更賜一年。頃者，大軍平燕都，下晉、冀，民被兵燹，困征斂，北平、燕南、河東、山西今年田租亦與蠲免。河南諸郡歸附，久欲惠之，西北未平，師過其地，是以未遑。今晉、冀平矣，西抵潼關，北界大河，南至唐、鄧、光、息，今年稅糧悉除之。」又詔曰：「應天、太平、鎮江、宣城、廣德供億浩穰。去歲蠲租，遇旱惠不及下。其再免諸郡及無為州今年租稅。」庚申，常遇春取大同。是月，倭寇山東濱海郡縣。；核对说明：原历纪年按本段及相邻年条核对，史料未载的具体日保留为空。", "status": "draft", "id": "0270dadb-5141-5161-a7a4-7deeddb08611", "subject_id": "4a48b6ce-d2df-5e12-a10e-59d19ab1a5e6", "source_id": "b5972b42-8e24-5a68-977e-16061d0248d8"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "下令减免北方田租和税粮"